```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private pending: (() => Promise<void>)[] = [];
  private running = 0;
  private idleWaiters: (() => void)[] = [];

  constructor(private readonly concurrency: number) {}

  /** Queues a job; the returned promise settles with its result or its final error. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.attempt(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves once nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private isIdle(): boolean {
    return this.running === 0 && this.pending.length === 0;
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const task = this.pending.shift()!;
      this.running++;
      void task().then(() => {
        this.running--;
        this.next();
        if (this.isIdle()) {
          for (const resolve of this.idleWaiters.splice(0)) resolve();
        }
      });
    }
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    for (let retries = 0; ; retries++) {
      try {
        return await job();
      } catch (err) {
        if (retries === 3) throw err;
      }
    }
  }
}
```

Attach a `.catch` (or `await`) to every `add()` call, because its promise rejects once a job has failed its first run and all three retries, and Node treats an unhandled rejection as fatal. Retries run immediately, with no backoff.

```go
// Package cli is a small command-line argument parser.
package cli

import (
	"errors"
	"fmt"
	"strings"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, usage, def string
	boolVal          *bool
	strVal           *string
}

// Parser holds flag definitions and the positional arguments found by Parse.
type Parser struct {
	name  string
	flags []*flagDef
	args  []string
}

// New returns a parser for the named program.
func New(name string) *Parser {
	return &Parser{name: name}
}

// Bool defines a boolean flag, false unless present.
func (p *Parser) Bool(name, usage string) *bool {
	v := new(bool)
	p.flags = append(p.flags, &flagDef{name: name, usage: usage, boolVal: v})
	return v
}

// String defines a flag that takes a value, given as --name value or --name=value.
func (p *Parser) String(name, def, usage string) *string {
	v := &def
	p.flags = append(p.flags, &flagDef{name: name, usage: usage, def: def, strVal: v})
	return v
}

// Args returns the positional arguments from the last Parse.
func (p *Parser) Args() []string {
	return p.args
}

// Parse reads args, normally os.Args[1:]. Flags and positional arguments may
// be mixed; everything after a bare "--" is positional.
func (p *Parser) Parse(args []string) error {
	p.args = nil
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			p.args = append(p.args, args[i+1:]...)
			return nil
		}
		if len(arg) < 2 || arg[0] != '-' {
			p.args = append(p.args, arg)
			continue
		}
		name, value, hasValue := strings.Cut(strings.TrimPrefix(strings.TrimPrefix(arg, "-"), "-"), "=")
		if name == "h" || name == "help" {
			return ErrHelp
		}
		f := p.lookup(name)
		if f == nil {
			return fmt.Errorf("unknown flag: %s", arg)
		}
		if f.boolVal != nil {
			if hasValue {
				return fmt.Errorf("flag --%s does not take a value", name)
			}
			*f.boolVal = true
			continue
		}
		if !hasValue {
			if i+1 >= len(args) {
				return fmt.Errorf("flag --%s needs a value", name)
			}
			i++
			value = args[i]
		}
		*f.strVal = value
	}
	return nil
}

// Usage returns a help message built from the flag definitions.
func (p *Parser) Usage() string {
	var b strings.Builder
	fmt.Fprintf(&b, "Usage: %s [flags] [args...]\n\nFlags:\n", p.name)
	for _, f := range p.flags {
		left := "--" + f.name
		if f.strVal != nil {
			left += " <value>"
		}
		fmt.Fprintf(&b, "  %-24s %s", left, f.usage)
		if f.def != "" {
			fmt.Fprintf(&b, " (default %q)", f.def)
		}
		b.WriteByte('\n')
	}
	fmt.Fprintf(&b, "  %-24s %s\n", "-h, --help", "show this help")
	return b.String()
}

func (p *Parser) lookup(name string) *flagDef {
	for _, f := range p.flags {
		if f.name == name {
			return f
		}
	}
	return nil
}
```

Define flags with `p.Bool` and `p.String`, call `p.Parse(os.Args[1:])`, and print `p.Usage()` when it returns `ErrHelp` or any other error. A positional argument that starts with a dash, such as `-5`, must come after `--`.

The standard library's `flag` package already covers all four requirements, if you would rather not maintain this.

```js
const express = require("express");
const { Pool } = require("pg");

const pool = new Pool();
const router = express.Router();

router.get("/orders", async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let after = null;
  if (req.query.cursor) {
    try {
      after = JSON.parse(Buffer.from(req.query.cursor, "base64url").toString());
      if (!Array.isArray(after) || after.length !== 2) throw new Error();
    } catch {
      return res.status(400).json({ error: "Invalid cursor" });
    }
  }

  try {
    // Fetch one extra row to learn whether another page exists. The cursor uses
    // created_at as text because a JS Date would drop the microseconds.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_created_at
         FROM orders
        ${after ? "WHERE (created_at, id) < ($2, $3)" : ""}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      after ? [limit + 1, ...after] : [limit + 1]
    );

    const page = rows.slice(0, limit);
    const last = page[page.length - 1];
    res.json({
      data: page.map(({ cursor_created_at, ...order }) => order),
      next_cursor:
        rows.length > limit
          ? Buffer.from(JSON.stringify([last.cursor_created_at, last.id])).toString("base64url")
          : null,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

Create the matching index with `CREATE INDEX ON orders (created_at DESC, id DESC);`, or each page will sort the whole table. The pool reads its connection details from the standard `PG*` environment variables.

The route returns every customer's orders, so add your own authentication and a `WHERE` filter on the owner before exposing it.

